figure %[output:66412ca0]
hold on %[output:66412ca0]
for i = 1:nT
    plot(K(i,:), PBS(i,:), '-o', 'Color', colores(i,:), 'LineWidth', 1.4, 'MarkerFaceColor', colores(i,:)); %[output:66412ca0]
end
