%%
%[text] # Conclusiones
%[text] - Los datos son consistentes con un MBG salvo por la normalidad (colas pesadas).
%[text] - Los dos pronósticos cumplen la meta de MAPE menor que 5 %.
%[text] - Los tres métodos numéricos reproducen Black-Scholes con errores por debajo del 0.1 %. El binomial y las diferencias finitas tienen error de discretización; Monte Carlo, error de muestreo.
%[text] - El error del binomial baja como $1/n$, el de Monte Carlo como $1/\\sqrt{M}$ y el de diferencias finitas como $\\Delta S^2$.
%[text] - El precio de la call baja con $K$ y sube con $T$; las opciones más baratas tienen el mayor error relativo. \
%%
%[text] ## Funciones locales
function tb = bateriaPruebas(r, dt, alpha, rez)
% Batería de pruebas del script del curso sobre un vector de retornos r.
    r  = r(:);
    Z  = (r - mean(r))/std(r);
    [hJB, pJB, eJB] = jbtest(r, alpha);
    [hKS, pKS, eKS] = kstest(Z, 'Alpha', alpha);
    [hAD, pAD, eAD] = adtest(r, 'Alpha', alpha);
    [hLI, pLI, eLI] = lillietest(r, 'Alpha', alpha);
    Et  = (r - mean(r))/sqrt(dt);
    [hADF, pADF, eADF] = adftest(Et, 'Alpha', alpha);
    [hAR,  pAR,  eAR ] = archtest(Et, 'Lags', rez, 'Alpha', alpha);
    [hLB2, pLB2, eLB2] = lbqtest(Et.^2, 'Lags', rez, 'Alpha', alpha);
    [hLB,  pLB,  eLB ] = lbqtest(r, 'Lags', rez, 'Alpha', alpha);
    Prueba = ["Jarque-Bera"; "Kolmogorov-Smirnov sobre Z"; "Anderson-Darling"; "Lilliefors"; ...
              "ADF sobre Et"; "ARCH de Engle sobre Et"; "Ljung-Box sobre Et^2"; "Ljung-Box sobre retornos"];
    Condicion = ["Normalidad"; "Normalidad"; "Normalidad"; "Normalidad"; "Estacionariedad"; ...
                 "Varianza constante"; "Varianza constante"; "Independencia"];
    H0 = ["Normal"; "Z ~ N(0,1)"; "Normal"; "Normal"; "Raíz unitaria"; "Sin efecto ARCH"; ...
          "Sin autocorrelación"; "Sin autocorrelación"];
    h           = double([hJB; hKS; hAD; hLI; hADF; hAR; hLB2; hLB]);
    ValorP      = [pJB; pKS; pAD; pLI; pADF; pAR; pLB2; pLB];
    Estadistico = [eJB; eKS; eAD; eLI; eADF; eAR; eLB2; eLB];
    hDeseado    = [0; 0; 0; 0; 1; 0; 0; 0];      % en la ADF se desea rechazar H0
    Cumple      = h == hDeseado;
    tb = table(Prueba, Condicion, H0, h, ValorP, Estadistico, hDeseado, Cumple);
end
function C = tablaCondiciones(tb, hayAlertaSalto, zMax, aporte2, EH, sEH)
% Resume la batería por condición del MBG.
    esFiable  = tb.Condicion == "Normalidad" & tb.Prueba ~= "Kolmogorov-Smirnov sobre Z";
    nRechazan = sum(~tb.Cumple(esFiable));
    p = @(nombre) tb.ValorP(tb.Prueba == nombre);
    Condicion = ["Estacionariedad"; "Independencia"; "Varianza constante"; "Normalidad"; ...
                 "Sin saltos"; "Carácter browniano (Hurst)"];
    Cumple = [all(tb.Cumple(tb.Condicion == "Estacionariedad")); all(tb.Cumple(tb.Condicion == "Independencia")); ...
              all(tb.Cumple(tb.Condicion == "Varianza constante")); nRechazan == 0; ~hayAlertaSalto; ...
              abs(EH - 0.5) <= 2*sEH];
    Evidencia = [string(sprintf('ADF: p = %.4f (aquí se desea rechazar)', p("ADF sobre Et"))); ...
                 string(sprintf('Ljung-Box sobre retornos: p = %.4f', p("Ljung-Box sobre retornos"))); ...
                 string(sprintf('ARCH: p = %.4f; Ljung-Box sobre Et^2: p = %.4f', p("ARCH de Engle sobre Et"), p("Ljung-Box sobre Et^2"))); ...
                 string(sprintf('Rechazan %d de 3 pruebas fiables; KS sobre Z: p = %.4f', nRechazan, p("Kolmogorov-Smirnov sobre Z"))); ...
                 string(sprintf('Mayor movimiento %.1f desv. est.; 2 días = %.1f %% de la varianza', zMax, aporte2)); ...
                 string(sprintf('H = %.3f, a %.1f desv. est. de 0.5', EH, abs(EH - 0.5)/sEH))];
    C = table(Condicion, Cumple, Evidencia);
end
function fac = pasoMBG(mu, sigma, dt, Z, esquema)
% Factor multiplicativo de un paso del MBG: X_nuevo = X_anterior .* fac
    switch esquema
        case 'euler',  fac = 1 + mu*dt + sigma*sqrt(dt).*Z;
        case 'exacta', fac = exp((mu - sigma^2/2)*dt + sigma*sqrt(dt).*Z);
    end
end
function [M, media, banda] = metricas(X, XP, nivel)
% Precisión y ajuste de un pronóstico XP (k x N) frente a los datos X (1 x N), días 2..N.
    a     = (1 - nivel)/2;
    media = mean(XP, 1);
    banda = quantile(XP, [a 1-a], 1);
    A  = X(2:end);  P = XP(:, 2:end);  Pm = media(2:end);
    mapeTray = 100*mean(abs(A - P)./abs(A), 2);
    M.MAPE_min   = min(mapeTray);
    M.MAPE_medio = mean(mapeTray);
    M.MAPE_max   = max(mapeTray);
    M.MAPE_media = 100*mean(abs(A - Pm)./abs(A));
    M.MAE_media  = mean(abs(A - Pm));
    M.RMSE_media = sqrt(mean((A - Pm).^2));
    dentro = A >= banda(1,2:end) & A <= banda(2,2:end);
    M.Cobertura_pct = 100*mean(dentro);
    M.DiasFuera     = sum(~dentro);
    c = corrcoef(A, Pm);
    M.R2_tray_media = c(1,2)^2;
    Ac = A - mean(A);  Pc = P - mean(P, 2);
    rTray = (Pc*Ac.')./(sqrt(sum(Pc.^2, 2))*sqrt(sum(Ac.^2)));
    M.R2_medio = mean(rTray.^2);
    M.MAPEcurso_medio = mean(100*mean(abs(XP - X)./abs(XP), 2));   % como mape(X, XI') del curso
end
function t = tablaMetricas(nombre, M, nivel, nRet)
% Una fila con las métricas de precisión y ajuste de un pronóstico.
    t = table(nombre, M.MAPE_min, M.MAPE_medio, M.MAPE_max, M.MAPE_media, M.MAE_media, M.RMSE_media, ...
              M.Cobertura_pct, M.DiasFuera, (1 - nivel)*nRet, M.R2_tray_media, ...
              'VariableNames', {'Pronostico', 'MAPE_min', 'MAPE_medio', 'MAPE_max', 'MAPE_tray_media', ...
                                'MAE_tray_media', 'RMSE_tray_media', 'Cobertura_pct', 'Dias_fuera', ...
                                'Dias_fuera_esperados', 'R2_tray_media'});
end
function figuraPronostico(X, XP, media, banda, F, cfg, tipo)
    nG = min(cfg.nGraficar, size(XP, 1));
    figure
    h1 = plot(F, XP(1:nG,:)', 'Color', 0.82*ones(1,3)); hold on
    h2 = plot(F, banda', 'r--', 'LineWidth', 1.5);
    h3 = plot(F, X, 'b', 'LineWidth', 1.2);
    h4 = plot(F, media, 'k', 'LineWidth', 1.2); hold off; grid on
    xlabel('Fecha'); ylabel('USD por EUR')
    title(sprintf('Pronóstico: trayectorias %s frente a los datos reales', tipo))
    legend([h1(1) h2(1) h3 h4], {sprintf('Trayectorias %s (%d de %d)', tipo, nG, size(XP,1)), ...
           sprintf('Banda %.0f %%', 100*cfg.nivelBanda), 'Datos reales', 'Valor esperado'}, 'Location', 'best')
end
function [C, d1, d2] = bsCall(S0, K, r, sigma, T)
% Call europea con la fórmula de Black-Scholes (PDF del curso).
    d1 = (log(S0./K) + (r + sigma.^2/2).*T)./(sigma.*sqrt(T));
    d2 = d1 - sigma.*sqrt(T);
    C  = S0.*normcdf(d1) - K.*exp(-r.*T).*normcdf(d2);
end
function Pp = bsPut(S0, K, r, sigma, T)
% Put europea con Black-Scholes (solo para la paridad put-call).
    d1 = (log(S0./K) + (r + sigma.^2/2).*T)./(sigma.*sqrt(T));
    d2 = d1 - sigma.*sqrt(T);
    Pp = K.*exp(-r.*T).*normcdf(-d2) - S0.*normcdf(-d1);
end
function p = probBinomial(r, sigma, dt, tipoP)
% Probabilidad neutral al riesgo de subir en el árbol.
    switch tipoP
        case 'curso', p = 1/2 + 1/(2*sigma)*(r - 1/2*sigma^2)*sqrt(dt);
        case 'crr'
            u = exp(sigma*sqrt(dt));  d = 1/u;
            p = (exp(r*dt) - d)/(u - d);
    end
end
function V = binomialCurso(S0, K, r, sigma, T, n, tipoP)
% Árbol binomial: mismo código del PDF del curso (pág. 8), con matrices completas.
    dt = T/n;  u = exp(sigma*sqrt(dt));  d = 1/u;  a = exp(-r*dt);
    p  = probBinomial(r, sigma, dt, tipoP);
    SF  = zeros(n+1, n+1);
    Opt = zeros(n+1, n+1);
    for i = 1:n+1
        for j = 1:i
            SF(i,j) = S0*u^(j-1)*d^(i-j);
        end
    end
    for j = 1:n+1
        Opt(n+1,j) = max(SF(n+1,j) - K, 0);
    end
    for i = n:-1:1
        for j = 1:i
            Opt(i,j) = a*((1-p)*Opt(i+1,j) + p*Opt(i+1,j+1));
        end
    end
    V = Opt(1,1);
end
function V = binomialVec(S0, K, r, sigma, T, n, tipoP)
% Mismo árbol, guardando solo un vector y calculando cada paso de una vez.
    dt = T/n;  u = exp(sigma*sqrt(dt));  d = 1/u;  a = exp(-r*dt);
    p  = probBinomial(r, sigma, dt, tipoP);
    j  = (0:n)';
    V  = max(S0*u.^j.*d.^(n-j) - K, 0);
    for i = n:-1:1
        V = a*((1-p)*V(1:i) + p*V(2:i+1));
    end
end
function M1 = mcCurso(S0, K, r, sigma, T, W, k, m)
% Monte Carlo: mismo código del PDF del curso (pág. 4), Euler con m pasos y bucles.
    dt = T/m;
    M1 = zeros(W, 1);  S1 = zeros(k, m+1);  f1 = zeros(k, 1);
    for n = 1:W
        rn = randn(k, m);
        for i = 1:k
            S1(i,1) = S0;
        end
        for i = 1:k
            for j = 2:m+1
                S1(i,j) = S1(i,j-1) + r*S1(i,j-1)*dt + sigma*S1(i,j-1)*sqrt(dt)*rn(i,j-1);
            end
        end
        for i = 1:k
            f1(i) = exp(-r*T)*max(S1(i,m+1) - K, 0);
        end
        M1(n) = mean(f1);
    end
end
function M = mcExacta(S0, K, r, sigma, T, W, k, antiteticas)
% Monte Carlo con la solución exacta en un paso; opcionalmente con variables antitéticas.
    M = zeros(W, 1);
    a = (r - sigma^2/2)*T;  b = sigma*sqrt(T);  desc = exp(-r*T);
    for n = 1:W
        if antiteticas
            e = randn(k/2, 1);  e = [e; -e];
        else
            e = randn(k, 1);
        end
        M(n) = desc*mean(max(S0*exp(a + b*e) - K, 0));
    end
end
function [V, MO] = dfCurso(S0, K, r, sigma, T, Smax, ds)
% Diferencias finitas explícitas: mismo código del PDF del curso (pág. 13), malla completa.
    ns  = round(Smax/ds);
    dtp = (ds/(sigma*Smax))^2;
    nt  = ceil(T/dtp);
    dt  = T/nt;
    S = zeros(1, ns+1);
    for j = 2:ns+1
        S(j) = S(j-1) + ds;
    end
    MO = zeros(nt+1, ns+1);
    MO(:, ns+1) = Smax - K;
    for j = 1:ns
        MO(nt+1, j) = max(S(j) - K, 0);
    end
    a = zeros(1, ns+1);  b = a;  c = a;
    for j = 1:ns+1
        a(j) = (dt/(1+r*dt))*((-1/2)*r*(j-1) + (1/2)*sigma^2*(j-1)^2);
        b(j) = (dt/(1+r*dt))*((1/dt) - sigma^2*(j-1)^2);
        c(j) = (dt/(1+r*dt))*((1/2)*r*(j-1) + (1/2)*sigma^2*(j-1)^2);
    end
    for i = nt:-1:1
        for j = 2:ns
            MO(i,j) = a(j)*MO(i+1,j-1) + b(j)*MO(i+1,j) + c(j)*MO(i+1,j+1);
        end
    end
    V = MO(1, round(S0/ds) + 1);
end
function [V, info] = dfVec(S0, K, r, sigma, T, Smax, ds, factorDt)
% Mismo esquema guardando solo la fila de tiempo actual; factorDt > 1 viola la estabilidad.
    ns  = round(Smax/ds);
    nt  = ceil(T/(factorDt*(ds/(sigma*Smax))^2));
    dt  = T/nt;
    jj  = 0:ns;
    f   = dt/(1+r*dt);
    a = f*(-r*jj/2 + sigma^2*jj.^2/2);
    b = f*(1/dt - sigma^2*jj.^2);
    c = f*( r*jj/2 + sigma^2*jj.^2/2);
    V = max(jj*ds - K, 0);  V(end) = Smax - K;
    in = 2:ns;
    for i = 1:nt
        V(in) = a(in).*V(in-1) + b(in).*V(in) + c(in).*V(in+1);
    end
    V = V(round(S0/ds) + 1);
    info = struct('nt', nt, 'ns', ns, 'minB', min(b));
end
function s = siNo(c)
    if c, s = 'sí'; else, s = 'no'; end
end

